const views=[...document.querySelectorAll('.view')];document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>{views.forEach(v=>v.classList.toggle('active',v.id===btn.dataset.view));document.querySelectorAll('header nav button').forEach(n=>n.classList.toggle('active',n.dataset.view===btn.dataset.view));window.scrollTo({top:0,behavior:'smooth'})}));const booking=document.querySelector('#booking'),shade=document.querySelector('#shade'),room=document.querySelector('#booking-room'),start=document.querySelector('#booking-start'),range=document.querySelector('#booking-range');document.querySelectorAll('.slot.open').forEach(slot=>slot.addEventListener('click',()=>{const r=slot.dataset.room||'Room 3';const t=slot.dataset.time||'7:00 PM';room.textContent=r;start.textContent=`Starts ${t}`;range.textContent=t.replace(' PM','')+'–'+nextHour(t);booking.classList.add('open');shade.classList.add('on');document.querySelectorAll('.slot').forEach(s=>s.classList.remove('chosen'));slot.classList.add('chosen')}));function nextHour(t){let [hm,mer]=t.split(' '),[h,m]=hm.split(':').map(Number);h=h%12+1;return `${h}:${String(m).padStart(2,'0')} ${mer}`}function close(){booking.classList.remove('open');shade.classList.remove('on')}document.querySelector('#close').addEventListener('click',close);shade.addEventListener('click',close);document.addEventListener('keydown',e=>e.key==='Escape'&&close());document.querySelectorAll('.duration button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.duration button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));